(function () {
  "use strict";
  var rules = {
    share: function (input) {
      return input.whole === 0 ? "A whole of zero has no share." : "Share: " + round(input.part / input.whole * 100) + "%";
    },
    average: function (input) {
      return input.days === 0 ? "Zero days leave nothing to divide by." : "Average for one day: " + round(input.total / input.days);
    }
  };
  function round(value) {
    return Math.round(value * 100) / 100;
  }
  document.querySelectorAll("form[data-sample-calculator]").forEach(function (form) {
    form.addEventListener("submit", function (event) {
      event.preventDefault();
      var input = {};
      form.querySelectorAll("input[name]").forEach(function (field) {
        input[field.name] = Number(field.value);
      });
      var valid = Object.keys(input).every(function (name) { return Number.isFinite(input[name]) && input[name] >= 0; });
      form.querySelector("output").textContent = valid ? rules[form.dataset.sampleCalculator](input) : "Enter numbers of zero or more.";
    });
  });
}());
